from past.builtins import basestring
import re

from taf.collectors.core.factories.factory import Factory
from taf.collectors.core.entities.local_executor import LocalExecutor
from .eventdecoder_converter import EventDecoderConverter


class EventDecoderConverterFactory(Factory):

    def create(self, configuration, existing_arguments):
        """
        Create an eventDecoder converter from configuration parameters and/or existing arguments.

        :param dict configuration:
            collection of configuration parameters for the object to be created and other objects,
            that might have to be created as prerequisites
        :param dict existing_arguments:
            existing arguments for the final constructor call, that don't need to be created
            (dict with constructor parameter name as key and argument value as value)
        """

        resulting_arguments = {}
        self._build_arguments(
            configuration=configuration,
            existing_arguments=existing_arguments,
            resulting_arguments=resulting_arguments)
        return EventDecoderConverter(**resulting_arguments)

    def _build_arguments(self, configuration, existing_arguments, resulting_arguments):
        super(EventDecoderConverterFactory, self)._build_arguments(
            configuration=configuration,
            existing_arguments=existing_arguments,
            resulting_arguments=resulting_arguments)

        resulting_arguments["input_file_path"] = configuration["input_file_path"]
        resulting_arguments["local_executor"] = self._create_local_executor()
        for parameter_name in [
                "output_file_path",
                "output_file_format",
                "tti_dec_path",
                "tti_dec_venv_path",
                "excel_csv_options",
                "eventdecoder_options",
                "eventdecoder_stdout_path"]:
            if parameter_name in configuration:
                resulting_arguments[parameter_name] = configuration[parameter_name]
            if configuration.get("output_file_format") in ("json", "excelCsv"):
                if configuration.get("conversion_filter") is not None:
                    resulting_arguments["filter_func"] = self._get_filter_func(configuration.get("conversion_filter"))

    def _create_local_executor(self):
        return LocalExecutor()

    def _get_filter_func(self, conversion_filter):
        if callable(conversion_filter):
            filter_func = conversion_filter
        elif isinstance(conversion_filter, basestring):
            def filter_func(event_dict):
                return bool(re.match(conversion_filter, list(event_dict.keys())[0]))
        else:
            raise TypeError(conversion_filter)
        return filter_func
